struct D3D9DeviceEx::War3SemanticDirectPartPacketLeaseState {
  struct Entry {
    war3::shadow::ShadowDrawPacket packet = {};
    war3::render::CurrentDrawAuthoritativeSample sample = {};
    const void* sceneNode = nullptr;
    uint64_t completenessKey = 0u;
    uint64_t recordSelectionKey = 0u;
    uint64_t selectionKey = 0u;
    uint64_t submittedPartIdentityKey = 0u;
    uint64_t manifestPartLeaseKey = 0u;
    uint64_t lastSubmittedFrame = 0u;
    // Diagnostics-only facts proved by the live eligibility gate. Preserve
    // them with a one-frame packet lease so restored parts do not repeat the
    // same resource/registry scans during successful-submit bookkeeping.
    bool statsDynamicUnitEvidenceKnown = false;
    bool statsDynamicUnitEvidence = false;
  };

  // Phase 7.25 core epoch planner：
  //   committedPartKeys 是“上一次被 live 观察证明过的完整 core part set”。
  //   它只在 live 提交集合是 committedPartKeys 的超集（即“覆盖旧 core”）
  //   时才被替换，不会因为一次 current-draw 观察丢帧而退化。
  //   observationPartKeys 用于在 committedPartKeys 未建立前做第二帧确认，
  //   避免把第一次偶然观察到的子集直接固定为 core。
  //
  // @thread_safety 仅在渲染线程 PopulateDirectSceneShadow 阶段访问。
  // @performance 每个 object 仅持有少量 64 位 key，常见规模为 <10 parts。
  struct ObjectCoreSet {
    // 已承认的 core part set，用于提交阶段的完整性校验。
    std::vector<uint64_t> committedPartKeys;
    // 最近一次看到的 live（非 lease）submitted parts，用于判断是否可以推进
    // committed set。
    std::vector<uint64_t> observationPartKeys;
    // committed 上一次被刷新的帧号（真正的 core epoch 时钟）。
    uint64_t lastCommitFrame = 0u;
    // 本对象最近被 live 提交过 part 的帧号，用于淘汰长期消失的对象。
    uint64_t lastLiveSubmittedFrame = 0u;
    // 上一次 observation 起始帧，超过 1 帧没有 live 证据时重新开始累积。
    uint64_t observationStartFrame = 0u;
    // Missing a packet/lease is not evidence of object removal. Each
    // committed part is retired only after two consecutive authoritative live
    // manifests omit it; tombstones bypass this map and retire immediately.
    std::unordered_map<uint64_t, uint8_t> authoritativeAbsenceStreak;
  };

  std::unordered_map<uint64_t, Entry> entries;
  std::unordered_map<uint64_t, ObjectCoreSet> objectCoreSets;
};

namespace {

// A draw-time exact capture rebases its private VB while retaining the
// original IB bytes.  vertexOffset alone is therefore not a complete replay
// contract: every consumer must carry the exact index domain (or the explicit
// full-domain fallback) that justified that offset.  Keeping this copy in one
// helper prevents DirectGrouped, the exact producer, and FastAppend from
// drifting into different validator inputs.
template <typename Entry>
void War3CopyDrawTimeReplayDomain(War3ShadowCasterDraw& draw,
                                  const Entry& entry) {
  draw.shadowActualIndexMin = entry.actualIndexMin;
  draw.shadowActualIndexMax = entry.actualIndexMax;
  draw.shadowActualIndexDomainKnown = entry.actualIndexDomainKnown;
  draw.shadowFullVertexDomainFallback = entry.fullVertexDomainFallback;
  draw.shadowIndexHintMismatch = entry.indexHintMismatch;
}

// Old final-caster traces contain 11,550 post-proof anonymous-marker Grace
// records, and every one falls within eight frames of the preceding exact
// rejection; none survives at age nine or later. Retain only this negative
// evidence window. This is not caster grace and never republishes geometry.
constexpr uint64_t kWar3AnonymousMarkerRejectionHoldFrames = 8u;

void* War3CurrentDrawInstanceIdentity(
    const war3::render::CurrentDrawContractRecord& contract) {
  if (contract.sceneNode != nullptr)
    return contract.sceneNode;
  if (contract.worldObjectEntry != nullptr)
    return contract.worldObjectEntry;
  return contract.unitPtr;
}

void* War3VisibleRenderableInstanceIdentity(
    const war3::render::VisibleRenderableRecord& record) {
  if (record.identity.sceneNode != nullptr)
    return record.identity.sceneNode;
  if (record.sceneNode != nullptr)
    return record.sceneNode;
  if (record.identity.worldObjectEntry != nullptr)
    return record.identity.worldObjectEntry;
  return record.identity.unitPtr;
}

uint32_t War3VisibleRenderableJHandle(
    const war3::render::VisibleRenderableRecord& record) {
  return record.identity.jHandle != 0u ? record.identity.jHandle
                                      : record.identity.handleId;
}

bool War3CurrentDrawContractMatchesSemanticInstance(
    const war3::render::CurrentDrawContractRecord& contract,
    const War3ShadowSemanticContext& semantic) {
  // A contract queried by a shared renderablePart may name a different unit.
  // Reject every contradictory identity and require at least one authoritative
  // identity component to agree before pairing its logical slice with the
  // current draw's GPU buffers.
  bool matched = false;
  if (semantic.sceneNode != nullptr && contract.sceneNode != nullptr) {
    if (semantic.sceneNode != contract.sceneNode)
      return false;
    matched = true;
  }
  if (semantic.worldObjectEntry != nullptr &&
      contract.worldObjectEntry != nullptr) {
    if (semantic.worldObjectEntry != contract.worldObjectEntry)
      return false;
    matched = true;
  }
  void* const semanticUnitPtr =
      semantic.object != nullptr ? semantic.object->unitPtr : nullptr;
  if (semanticUnitPtr != nullptr && contract.unitPtr != nullptr) {
    if (semanticUnitPtr != contract.unitPtr)
      return false;
    matched = true;
  }
  if (semantic.jHandle != 0u && contract.jHandle != 0u) {
    if (semantic.jHandle != contract.jHandle)
      return false;
    matched = true;
  }
  return matched;
}

// Stage11 construction effects are rendered as child runtime models.  The
// semantic bridge names the owning building/destructible, while the native
// dispatch scope names the child scene node and renderable part that actually
// supplied the D3D draw.  Treating those two identity domains as one made the
// exact current-frame producer reject UBirth and Night-Elf construction
// attachments before their VB/IB could be captured.
//
// Keep geometry and owner identity separate: geometry always comes from the
// active native dispatch, while gameplay classification (rawcode, blocker,
// object kind) remains tied to an independently matching owner identity.
struct War3CurrentDrawCaptureBinding {
  void* renderablePart = nullptr;
  void* sceneNode = nullptr;
  void* meshPayload = nullptr;
  war3::render::CurrentDrawDispatchDomain dispatchDomain =
      war3::render::CurrentDrawDispatchDomain::Unknown;
  bool layerKnown = false;
  uint32_t layerIndex = 0u;
  bool attachmentBridge = false;
};

bool War3ResolveCurrentDrawCaptureBinding(
    const War3ShadowSemanticContext& semantic,
    const war3::render::CurrentDrawDispatchContext& dispatch,
    War3CurrentDrawCaptureBinding& out) {
  out = {};
  if (!dispatch.valid || dispatch.renderablePart == nullptr)
    return false;

  const bool transparentType0 =
      dispatch.domain ==
      war3::render::CurrentDrawDispatchDomain::TransparentType0;
  if (transparentType0) {
    if (dispatch.layerKnown ||
        dispatch.layerIndex != war3::render::kRenderQueueUnknownLayerIndex ||
        dispatch.meshPayload == nullptr) {
      return false;
    }
  } else if (!dispatch.layerKnown ||
             (dispatch.domain !=
                  war3::render::CurrentDrawDispatchDomain::Common &&
              dispatch.domain !=
                  war3::render::CurrentDrawDispatchDomain::Special)) {
    return false;
  }

  out.renderablePart = dispatch.renderablePart;
  out.sceneNode = dispatch.sceneNode;
  out.meshPayload = dispatch.meshPayload;
  out.dispatchDomain = dispatch.domain;
  out.layerKnown = dispatch.layerKnown;
  out.layerIndex = dispatch.layerIndex;
  out.attachmentBridge =
      transparentType0 ||
      semantic.renderablePart != dispatch.renderablePart ||
      (semantic.sceneNode != nullptr && dispatch.sceneNode != nullptr &&
       semantic.sceneNode != dispatch.sceneNode);
  if (!out.attachmentBridge)
    return semantic.renderablePart != nullptr;

  // A child draw may differ from its owner's scene node/part, but it must
  // still have a strong owner witness.  Rawcode/model name alone is not an
  // instance identity and cannot authorize capture or publication.
  const void* const semanticUnitPtr =
      semantic.object != nullptr ? semantic.object->unitPtr : nullptr;
  const uint32_t semanticJHandle =
      semantic.jHandle != 0u
          ? semantic.jHandle
          : (semantic.object != nullptr ? semantic.object->jHandle : 0u);
  return semantic.worldObjectEntry != nullptr || semanticUnitPtr != nullptr ||
         semanticJHandle != 0u;
}

bool War3CurrentDrawContractMatchesCaptureBinding(
    const war3::render::CurrentDrawContractRecord& contract,
    const War3ShadowSemanticContext& semantic,
    const War3CurrentDrawCaptureBinding& binding) {
  if (!contract.known ||
      contract.renderablePart != binding.renderablePart ||
      contract.layerIndex != binding.layerIndex) {
    return false;
  }
  if (binding.sceneNode != nullptr && contract.sceneNode != nullptr &&
      binding.sceneNode != contract.sceneNode) {
    return false;
  }
  if (!binding.attachmentBridge)
    return War3CurrentDrawContractMatchesSemanticInstance(contract, semantic);

  // Do not compare semantic.sceneNode here: for a construction attachment it
  // intentionally names the parent while contract.sceneNode names the child.
  // Every overlapping owner component must agree, and at least one must
  // match, so a shared model part can never borrow another instance's draw.
  bool ownerMatched = false;
  if (semantic.worldObjectEntry != nullptr &&
      contract.worldObjectEntry != nullptr) {
    if (semantic.worldObjectEntry != contract.worldObjectEntry)
      return false;
    ownerMatched = true;
  }
  void* const semanticUnitPtr =
      semantic.object != nullptr ? semantic.object->unitPtr : nullptr;
  if (semanticUnitPtr != nullptr && contract.unitPtr != nullptr) {
    if (semanticUnitPtr != contract.unitPtr)
      return false;
    ownerMatched = true;
  }
  const uint32_t semanticJHandle =
      semantic.jHandle != 0u
          ? semantic.jHandle
          : (semantic.object != nullptr ? semantic.object->jHandle : 0u);
  if (semanticJHandle != 0u && contract.jHandle != 0u) {
    if (semanticJHandle != contract.jHandle)
      return false;
    ownerMatched = true;
  }
  return ownerMatched;
}

bool War3CurrentDrawContractMatchesRenderableInstance(
    const war3::render::CurrentDrawContractRecord& contract,
    const war3::shadow::ShadowRenderableRecord& renderable) {
  bool matched = false;
  if (contract.renderablePart != nullptr && renderable.renderablePart != nullptr) {
    if (contract.renderablePart != renderable.renderablePart)
      return false;
    matched = true;
  }
  if (contract.sceneNode != nullptr && renderable.sceneNode != nullptr) {
    if (contract.sceneNode != renderable.sceneNode)
      return false;
    matched = true;
  }
  if (contract.worldObjectEntry != nullptr &&
      renderable.worldObjectEntry != nullptr) {
    if (contract.worldObjectEntry != renderable.worldObjectEntry)
      return false;
    matched = true;
  }
  if (contract.unitPtr != nullptr && renderable.unitPtr != nullptr) {
    if (contract.unitPtr != renderable.unitPtr)
      return false;
    matched = true;
  }
  if (contract.jHandle != 0u && renderable.jHandle != 0u) {
    if (contract.jHandle != renderable.jHandle)
      return false;
    matched = true;
  }
  return matched;
}

bool War3VisibleRenderableMatchesDrawTimeKey(
    const war3::render::VisibleRenderableRecord& record,
    const War3DrawTimeVBCacheKey& key) {
  if (record.renderablePart != key.renderablePart ||
      record.layerIndex != key.layerIndex) {
    return false;
  }
  if (record.meshData != nullptr && record.meshData != key.meshPayloadPtr)
    return false;

  bool matched = false;
  void* const visibleIdentity = War3VisibleRenderableInstanceIdentity(record);
  if (visibleIdentity != nullptr && key.instanceIdentity != nullptr) {
    if (visibleIdentity != key.instanceIdentity)
      return false;
    matched = true;
  }
  const uint32_t visibleJHandle = War3VisibleRenderableJHandle(record);
  if (visibleJHandle != 0u && key.jHandle != 0u) {
    if (visibleJHandle != key.jHandle)
      return false;
    matched = true;
  }
  return matched;
}

War3DrawTimeVBCacheKey War3MakeDrawTimeVBCacheKey(
    void* renderablePart,
    uint32_t layerIndex,
    const war3::render::CurrentDrawContractRecord* contract,
    uint64_t mapEpoch) {
  War3DrawTimeVBCacheKey key = {};
  key.mapEpoch = mapEpoch;
  key.renderablePart = renderablePart;
  key.layerIndex = layerIndex;
  if (contract != nullptr &&
      war3::render::CurrentDrawContractHasCanonicalIdentity(*contract) &&
      contract->renderablePart == renderablePart &&
      contract->layerIndex == layerIndex) {
    key.instanceIdentity = War3CurrentDrawInstanceIdentity(*contract);
    key.meshPayloadPtr = contract->meshPayloadPtr;
    key.jHandle = contract->jHandle;
    key.payloadWord108 = contract->payloadWord108;
    key.payloadWord11C = contract->payloadWord11C;
  }
  return key;
}

bool War3CurrentDrawContractNamesExactSlice(
    void* renderablePart,
    uint32_t layerIndex,
    const war3::render::CurrentDrawContractRecord& contract) {
  return war3::render::CurrentDrawContractHasCanonicalIdentity(contract) &&
         contract.renderablePart == renderablePart &&
         contract.layerIndex == layerIndex &&
         contract.meshPayloadPtr != nullptr &&
         (War3CurrentDrawInstanceIdentity(contract) != nullptr ||
          contract.jHandle != 0u);
}

war3::shadow::War3ShadowDrawMetadataQuery War3MakeShadowMetadataQuery(
    const war3::render::CurrentDrawContractRecord& contract,
    uint64_t materialSignatureHash) {
  war3::shadow::War3ShadowDrawMetadataQuery query = {};
  query.instanceIdentity = War3CurrentDrawInstanceIdentity(contract);
  query.sceneNode = contract.sceneNode;
  query.renderablePart = contract.renderablePart;
  query.meshPayloadPtr = contract.meshPayloadPtr;
  query.worldObjectEntry = contract.worldObjectEntry;
  query.unitPtr = contract.unitPtr;
  query.jHandle = contract.jHandle;
  query.layerIndex = contract.layerIndex;
  query.producerStage =
      contract.producerStage >= 0 ? contract.producerStage : contract.stage;
  query.payloadWord108 = contract.payloadWord108;
  query.payloadWord11C = contract.payloadWord11C;
  query.materialSignatureHash = materialSignatureHash;
  return query;
}

war3::shadow::War3ShadowDrawMetadataKey War3MakeShadowMetadataKey(
    const war3::shadow::War3ShadowDrawMetadataQuery& query,
    const Rc<DxvkImageView>& texture) {
  war3::shadow::War3ShadowDrawMetadataKey key = {};
  key.instanceIdentity = query.instanceIdentity;
  key.sceneNode = query.sceneNode;
  key.renderablePart = query.renderablePart;
  key.meshPayloadPtr = query.meshPayloadPtr;
  key.worldObjectEntry = query.worldObjectEntry;
  key.unitPtr = query.unitPtr;
  key.jHandle = query.jHandle;
  key.layerIndex = query.layerIndex;
  key.producerStage = query.producerStage;
  key.payloadWord108 = query.payloadWord108;
  key.payloadWord11C = query.payloadWord11C;
  key.materialSignatureHash = query.materialSignatureHash;
  key.textureIdentity = texture.ptr();
  key.textureGeneration =
      war3::shadow::War3ShadowTextureGeneration(texture);
  return key;
}

template <typename T, typename = void>
struct War3HasNativeRangePoisoned : std::false_type {};

template <typename T>
struct War3HasNativeRangePoisoned<
    T, std::void_t<decltype(std::declval<const T&>().nativeRangePoisoned)>>
    : std::true_type {};

template <typename T, typename = void>
struct War3HasNativeSuppressionFlag : std::false_type {};

template <typename T>
struct War3HasNativeSuppressionFlag<
    T, std::void_t<decltype(std::declval<const T&>().requiresSuppression)>>
    : std::true_type {};

template <typename T>
bool War3NativeDipRangePoisonedImpl(const T& observation) {
  bool poisoned = observation.sourceUploadKernelBypassed;
  if constexpr (War3HasNativeRangePoisoned<T>::value)
    poisoned = poisoned || observation.nativeRangePoisoned;
  if constexpr (War3HasNativeSuppressionFlag<T>::value)
    poisoned = poisoned || observation.requiresSuppression;
  return poisoned;
}

bool War3NativeDipRangePoisoned(
    const war3::gpu_skin::NativeDipObservation& observation) {
  return War3NativeDipRangePoisonedImpl(observation);
}

bool War3BuildExactGpuSkinDrawInput(
    const war3::gpu_skin::GpuSkinResolvedDraw& resolved,
    uint64_t mapEpoch,
    uint64_t deviceEpoch,
    uint32_t vertexCount,
    bool irreversible,
    War3GpuSkinDrawInput& result) {
  using namespace war3::gpu_skin;
  result = {};

  constexpr uint32_t expectedConsumers =
      static_cast<uint32_t>(GpuSkinConsumerBits::Main) |
      static_cast<uint32_t>(GpuSkinConsumerBits::Shadow);
  const GpuSkinInputLease& input = resolved.inputLease;
  const OutputLease& output = resolved.lease;
  const GpuSkinStaticSourceLayout layout = GetGpuSkinStaticSourceLayout(
      vertexCount, input.desc.sourceUvLayerCount);
  const uint64_t paletteBytes =
      uint64_t(input.desc.paletteMatrixCount) * 48u;

  const bool computeOutputCapability =
      output.desc.vertexCount == vertexCount &&
      output.desc.vertexStride == GetGpuSkinFvfStride(2u);
  const bool inputOnlyCapability =
      output.leaseId == input.storageLeaseId &&
      output.pageId == input.storagePageId &&
      output.pageGeneration == input.storagePageGeneration &&
      output.desc.vertexCount == 0u && output.desc.vertexStride == 0u &&
      output.desc.byteOffset == input.desc.paletteByteOffset &&
      output.desc.byteLength == input.desc.paletteByteLength &&
      output.slice.buffer() == input.palette.buffer() &&
      output.slice.offset() == input.palette.offset() &&
      output.slice.length() == input.palette.length();
  // VS-A 以 compute output 兜底；VS-B0/B1 则允许同一个 palette storage
  // lease 作为 capability。三者仍必须共享 token/epoch，并只接受已经证明的
  // 0x112 静态布局；B1 还会在调用处要求不可逆输入资源能力。
  const bool exact = static_cast<bool>(resolved) &&
      static_cast<bool>(input) && output.leaseId != 0u &&
      resolved.key.batchId != 0u && resolved.key.token != 0u &&
      resolved.key.frameTag != 0u && resolved.key.outputFormat == 2u &&
      output.desc.mapEpoch == mapEpoch &&
      output.desc.deviceEpoch == deviceEpoch &&
      output.desc.frameTag == resolved.key.frameTag &&
      output.desc.token == resolved.key.token &&
      (computeOutputCapability || inputOnlyCapability) &&
      (!inputOnlyCapability ||
       (output.desc.consumerBits != 0u &&
        (output.desc.consumerBits & ~expectedConsumers) == 0u)) &&
      input.desc.mapEpoch == output.desc.mapEpoch &&
      input.desc.deviceEpoch == output.desc.deviceEpoch &&
      input.desc.frameTag == output.desc.frameTag &&
      input.desc.token == output.desc.token &&
      input.desc.dispatchEpoch == output.desc.dispatchEpoch &&
      input.desc.uploadEpoch == output.desc.uploadEpoch &&
      input.desc.dispatchEpoch != 0u && input.desc.uploadEpoch != 0u &&
      input.desc.vertexCount == vertexCount &&
      input.desc.paletteMatrixCount != 0u &&
      input.desc.paletteMatrixCount <= 256u &&
      input.desc.sourceUvLayerCount == 1u &&
      input.desc.outputFormat == 2u &&
      input.desc.layoutGeneration == 1u &&
      input.desc.consumerBits == expectedConsumers &&
      input.desc.staticByteOffset == input.staticSource.offset() &&
      input.desc.staticByteLength == input.staticSource.length() &&
      input.desc.paletteByteOffset == input.palette.offset() &&
      input.desc.paletteByteLength == input.palette.length() &&
      layout.byteSize != 0u &&
      layout.byteSize == input.staticSource.length() &&
      paletteBytes != 0u && paletteBytes == input.palette.length() &&
      input.storageLeaseId != 0u &&
      input.storagePageGeneration != 0u && input.storagePageId != 0u &&
      input.staticSource.buffer() != nullptr &&
      input.palette.buffer() != nullptr &&
      (input.staticSource.buffer()->info().usage &
       VK_BUFFER_USAGE_STORAGE_BUFFER_BIT) != 0u &&
      (input.staticSource.buffer()->info().stages &
       VK_PIPELINE_STAGE_VERTEX_SHADER_BIT) != 0u &&
      (input.staticSource.buffer()->info().access &
       VK_ACCESS_SHADER_READ_BIT) != 0u &&
      (!irreversible ||
       ((input.staticSource.buffer()->info().usage &
         VK_BUFFER_USAGE_VERTEX_BUFFER_BIT) != 0u &&
        (input.staticSource.buffer()->info().stages &
         VK_PIPELINE_STAGE_VERTEX_INPUT_BIT) != 0u &&
        (input.staticSource.buffer()->info().access &
         VK_ACCESS_VERTEX_ATTRIBUTE_READ_BIT) != 0u)) &&
      (input.palette.buffer()->info().usage &
       (VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
        VK_BUFFER_USAGE_TRANSFER_DST_BIT)) ==
          (VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
           VK_BUFFER_USAGE_TRANSFER_DST_BIT) &&
      (input.palette.buffer()->info().stages &
       (VK_PIPELINE_STAGE_VERTEX_SHADER_BIT |
        VK_PIPELINE_STAGE_TRANSFER_BIT)) ==
          (VK_PIPELINE_STAGE_VERTEX_SHADER_BIT |
           VK_PIPELINE_STAGE_TRANSFER_BIT) &&
      (input.palette.buffer()->info().access &
       (VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_TRANSFER_WRITE_BIT)) ==
          (VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_TRANSFER_WRITE_BIT);
  if (!exact)
    return false;

  result.desc = input.desc;
  result.staticSource = input.staticSource;
  result.palette = input.palette;
  result.storageLeaseId = input.storageLeaseId;
  result.storagePageGeneration = input.storagePageGeneration;
  result.storagePageId = input.storagePageId;
  result.irreversible = irreversible;
  result.valid = true;
  return static_cast<bool>(result);
}

war3::gpu_skin::NativeVertexStorageDiagnostics
War3GpuSkinVertexStorageDiagnostics(D3D9CommonBuffer* common) {
  using namespace war3::gpu_skin;
  NativeVertexStorageDiagnostics result = {};
  if (common == nullptr)
    return result;

  const Rc<DxvkBuffer>& real =
      common->GetBuffer<D3D9_COMMON_BUFFER_TYPE_REAL>();
  const Rc<DxvkBuffer>& mapping =
      common->GetBuffer<D3D9_COMMON_BUFFER_TYPE_MAPPING>();
  if (real.ptr() == mapping.ptr()) {
    const uint64_t generation = real != nullptr
        ? real->diagnosticStorageGeneration() : 0u;
    result.realStorageGeneration = generation;
    result.mappingStorageGeneration = generation;
  } else {
    result.realStorageGeneration = real != nullptr
        ? real->diagnosticStorageGeneration() : 0u;
    result.mappingStorageGeneration = mapping != nullptr
        ? mapping->diagnosticStorageGeneration() : 0u;
  }
  result.mapAllocationGeneration =
      common->War3MapAllocationGeneration();
  result.mapMode = common->GetMapMode() ==
          D3D9_COMMON_BUFFER_MAP_MODE_DIRECT
      ? kNativeVertexMapModeDirect : kNativeVertexMapModeBuffer;
  D3D9CommonBuffer::War3ActiveLock activeLock = {};
  result.activeLock = common->War3GetActiveLock(activeLock);
  result.activeLockFlags = result.activeLock ? activeLock.flags : 0u;
  return result;
}

inline constexpr uint64_t kWar3GpuSkinDrawChainTimingPeriod = 256u;
inline constexpr uint64_t kWar3GpuSkinDrawChainTimingPhase = 0x5au;
thread_local uint64_t t_war3GpuSkinDrawChainTimingOrdinal = 0u;

static_assert(
    (kWar3GpuSkinDrawChainTimingPeriod &
     (kWar3GpuSkinDrawChainTimingPeriod - 1u)) == 0u,
    "GPU-skin draw-chain timing requires a power-of-two sample period");
static_assert(
    kWar3GpuSkinDrawChainTimingPhase <
        kWar3GpuSkinDrawChainTimingPeriod,
    "GPU-skin draw-chain timing phase must be inside the sample period");

inline bool War3GpuSkinDrawChainTimingEnabled() {
  static const bool enabled = []() {
    const char* value =
        std::getenv("DXVK_WAR3_GPU_SKIN_DRAW_CHAIN_TIMING");
    return value != nullptr && value[0] == '1' && value[1] == '\0';
  }();
  return enabled;
}

class War3GpuSkinDrawChainCpuScope final {
public:
  War3GpuSkinDrawChainCpuScope(bool sampled, const char* name) {
    if (sampled) {
      m_scope.emplace(
          war3::War3PerfMonitor::instance().cpuScope(name));
    }
  }

  War3GpuSkinDrawChainCpuScope(
      const War3GpuSkinDrawChainCpuScope&) = delete;
  War3GpuSkinDrawChainCpuScope& operator=(
      const War3GpuSkinDrawChainCpuScope&) = delete;

private:
  // When the runtime gate is false this optional remains disengaged, so the
  // hot path never calls the monitor or ScopedCpuScope's out-of-line dtor.
  std::optional<war3::War3PerfMonitor::ScopedCpuScope> m_scope;
};

inline bool War3SampleNextGpuSkinDrawChainLeaf() {
  // Sampling admission itself performs only the cached-bool branch. Each
  // conditional stage scope still has a predictable disengaged-optional check
  // when the gate is false, but cannot enter the monitor/QPC/locking path.
  // The ordinal belongs to physical leaves, so split controllers,
  // auto-instancing suppression and invalid/empty DIPs must return before
  // calling this helper.
  if (likely(!War3GpuSkinDrawChainTimingEnabled()))
    return false;
  const uint64_t ordinal = ++t_war3GpuSkinDrawChainTimingOrdinal;
  return (ordinal & (kWar3GpuSkinDrawChainTimingPeriod - 1u)) ==
      kWar3GpuSkinDrawChainTimingPhase;
}

enum class War3GpuSkinDipProductionClass : uint8_t {
  Outside = 0,
  NoUpload,
  Correlated,
};

thread_local uint64_t t_war3GpuSkinDipProductionTimingOrdinal = 0u;

static_assert(
    (war3::gpu_skin::kNativeProductionTimingSamplePeriod &
     (war3::gpu_skin::kNativeProductionTimingSamplePeriod - 1u)) == 0u,
    "production timing event ordinals require a power-of-two period");

class War3GpuSkinDipProductionTiming final {
public:
  using NativeDipObservation = war3::gpu_skin::NativeDipObservation;
  using NativeProductionTimingEntry =
      war3::gpu_skin::NativeProductionTimingEntry;
  using NativeProductionTimingStage =
      war3::gpu_skin::NativeProductionTimingStage;

  War3GpuSkinDipProductionTiming() noexcept {
    if (!war3::gpu_skin::NativeBridgeProductionLightTimingEnabled())
      return;
    const uint64_t ordinal =
        ++t_war3GpuSkinDipProductionTimingOrdinal;
    m_sampled =
        (ordinal &
         (war3::gpu_skin::kNativeProductionTimingSamplePeriod - 1u)) ==
        war3::gpu_skin::kNativeProductionTimingSamplePhase;
    if (m_sampled)
      m_rootStart = dxvk::high_resolution_clock::get_counter();
  }

  ~War3GpuSkinDipProductionTiming() noexcept {
    if (!m_sampled || !m_bridgeRecorded)
      return;
    // Capture the inclusive endpoint before publishing the entire physical
    // DIP sample in one writer generation. Root and bridge always share one
    // class; Resolve is present only when the manager-resolution gate ran.
    const int64_t rootEnd = dxvk::high_resolution_clock::get_counter();
    std::array<NativeProductionTimingEntry, 3u> entries{};
    size_t count = 0u;
    entries[count++] = {
        DeviceRootStage(m_class), ElapsedTicks(m_rootStart, rootEnd)};
    entries[count++] = {BridgeStage(m_class), m_bridgeTicks};
    if (m_resolveRecorded)
      entries[count++] = {ResolveStage(m_class), m_resolveTicks};
    war3::gpu_skin::RecordNativeProductionTimingBatch(
        entries.data(), count);
  }

  War3GpuSkinDipProductionTiming(
      const War3GpuSkinDipProductionTiming&) = delete;
  War3GpuSkinDipProductionTiming& operator=(
      const War3GpuSkinDipProductionTiming&) = delete;

  int64_t BeginStage() const noexcept {
    return m_sampled ? dxvk::high_resolution_clock::get_counter() : 0;
  }

  void EndBridge(
      int64_t start, const NativeDipObservation& observation) noexcept {
    if (!m_sampled)
      return;
    const int64_t end = dxvk::high_resolution_clock::get_counter();
    m_bridgeTicks = ElapsedTicks(start, end);
    m_class = observation.correlated
        ? War3GpuSkinDipProductionClass::Correlated
        : observation.epoch.dispatchEpoch == 0u
        ? War3GpuSkinDipProductionClass::Outside
        : War3GpuSkinDipProductionClass::NoUpload;
    m_bridgeRecorded = true;
  }

  void EndResolve(int64_t start) noexcept {
    if (!m_sampled)
      return;
    const int64_t end = dxvk::high_resolution_clock::get_counter();
    m_resolveTicks = ElapsedTicks(start, end);
    m_resolveRecorded = true;
  }

private:
  static uint64_t ElapsedTicks(int64_t start, int64_t end) noexcept {
    return end > start ? uint64_t(end - start) : 0u;
  }

  static NativeProductionTimingStage DeviceRootStage(
      War3GpuSkinDipProductionClass value) noexcept {
    switch (value) {
      case War3GpuSkinDipProductionClass::Outside:
        return NativeProductionTimingStage::DipDeviceRootOutside;
      case War3GpuSkinDipProductionClass::NoUpload:
        return NativeProductionTimingStage::DipDeviceRootNoUpload;
      case War3GpuSkinDipProductionClass::Correlated:
        return NativeProductionTimingStage::DipDeviceRootCorrelated;
    }
    return NativeProductionTimingStage::DipDeviceRootOutside;
  }

  static NativeProductionTimingStage BridgeStage(
      War3GpuSkinDipProductionClass value) noexcept {
    switch (value) {
      case War3GpuSkinDipProductionClass::Outside:
        return NativeProductionTimingStage::DipBridgeOutside;
      case War3GpuSkinDipProductionClass::NoUpload:
        return NativeProductionTimingStage::DipBridgeNoUpload;
      case War3GpuSkinDipProductionClass::Correlated:
        return NativeProductionTimingStage::DipBridgeCorrelated;
    }
    return NativeProductionTimingStage::DipBridgeOutside;
  }

  static NativeProductionTimingStage ResolveStage(
      War3GpuSkinDipProductionClass value) noexcept {
    switch (value) {
      case War3GpuSkinDipProductionClass::Outside:
        return NativeProductionTimingStage::DipResolveOutside;
      case War3GpuSkinDipProductionClass::NoUpload:
        return NativeProductionTimingStage::DipResolveNoUpload;
      case War3GpuSkinDipProductionClass::Correlated:
        return NativeProductionTimingStage::DipResolveCorrelated;
    }
    return NativeProductionTimingStage::DipResolveOutside;
  }

  bool m_sampled = false;
  bool m_bridgeRecorded = false;
  bool m_resolveRecorded = false;
  War3GpuSkinDipProductionClass m_class =
      War3GpuSkinDipProductionClass::Outside;
  int64_t m_rootStart = 0;
  uint64_t m_bridgeTicks = 0u;
  uint64_t m_resolveTicks = 0u;
};

class War3GpuSkinConsumerSettlement {
public:
  using GpuSkinConsumerBits = war3::gpu_skin::GpuSkinConsumerBits;
  using GpuSkinConsumerFailure = war3::gpu_skin::GpuSkinConsumerFailure;
  using GpuSkinResolvedDraw = war3::gpu_skin::GpuSkinResolvedDraw;
  using War3GpuSkinManager = war3::gpu_skin::War3GpuSkinManager;

  enum class IrreversibleFailureScope : uint8_t {
    SingleConsumer,
    AllPending,
  };

  War3GpuSkinConsumerSettlement(
      War3GpuSkinManager* manager,
      const GpuSkinResolvedDraw* resolved,
      GpuSkinConsumerBits consumer,
      IrreversibleFailureScope irreversibleFailureScope)
      : m_consumer(consumer),
        m_irreversibleFailureScope(irreversibleFailureScope) {
    reset(manager, resolved);
  }

  ~War3GpuSkinConsumerSettlement() {
    fail();
  }

  War3GpuSkinConsumerSettlement(
      const War3GpuSkinConsumerSettlement&) = delete;
  War3GpuSkinConsumerSettlement& operator=(
      const War3GpuSkinConsumerSettlement&) = delete;

  bool reset(War3GpuSkinManager* manager,
             const GpuSkinResolvedDraw* resolved) {
    const uint32_t consumerBit = static_cast<uint32_t>(m_consumer);
    // Shadow may be reserved by the explicit plan before ResolveShadowLease
    // returns its consumer-specific view. The guard owns that pending plan bit
    // immediately so every capture early return still reaches one terminal.
    const bool valid = manager != nullptr && resolved != nullptr &&
        static_cast<bool>(*resolved) && resolved->leaseId != 0u &&
        resolved->lease.leaseId == resolved->leaseId &&
        (((resolved->lease.desc.consumerBits & consumerBit) != 0u) ||
         ((resolved->plan.leaseBacked & consumerBit) != 0u));
    const bool sameReservation = m_active && valid && manager == m_manager &&
        m_resolved->leaseId == resolved->leaseId &&
        m_resolved->key.frameTag == resolved->key.frameTag &&
        m_resolved->key.flushEpoch == resolved->key.flushEpoch &&
        m_resolved->key.batchId == resolved->key.batchId &&
        m_resolved->key.renderablePart == resolved->key.renderablePart &&
        m_resolved->key.geosetData == resolved->key.geosetData &&
        m_resolved->key.layerIndex == resolved->key.layerIndex &&
        m_resolved->key.outputFormat == resolved->key.outputFormat &&
        m_resolved->key.token == resolved->key.token;
    if (sameReservation) {
      // ResolveShadowLease upgrades the same pending plan bit to an exact
      // resolved lease. Adopting it must not fail the old local guard first.
      m_resolved = *resolved;
      return true;
    }
    if (m_active && !fail())
      return false;
    m_manager = manager;
    if (!valid) {
      return false;
    }
    m_resolved = *resolved;
    m_active = true;
    return true;
  }

  bool active() const {
    return m_active;
  }

  void disarm() {
    m_active = false;
  }

  bool commit() {
    if (!m_active)
      return false;
    if (!m_manager->CommitConsumer(
            m_resolved->key, m_resolved->leaseId, m_consumer)) {
      return false;
    }
    m_active = false;
    return true;
  }

  bool fail() {
    if (!m_active)
      return true;
    const auto failure = m_resolved->nativeUploadBypassed
        ? GpuSkinConsumerFailure::SuppressAndFuse
        : GpuSkinConsumerFailure::CpuFallback;
    if (failure == GpuSkinConsumerFailure::SuppressAndFuse &&
        m_irreversibleFailureScope ==
            IrreversibleFailureScope::AllPending) {
      m_manager->TerminateIrreversibleBypassConsumers(*m_resolved);
      m_active = false;
      return true;
    }
    if (m_manager->FailConsumer(
            m_resolved->key, m_resolved->leaseId, m_consumer, failure)) {
      m_active = false;
      return true;
    }
    return false;
  }

private:
  War3GpuSkinManager* m_manager = nullptr;
  // Most capture calls have no GPU-skin reservation. Avoid value-initializing
  // the 552-byte resolved record on every Main/Outline/Shadow guard; construct
  // it only when this guard actually owns a live consumer reservation.
  std::optional<GpuSkinResolvedDraw> m_resolved;
  GpuSkinConsumerBits m_consumer = GpuSkinConsumerBits::Main;
  IrreversibleFailureScope m_irreversibleFailureScope =
      IrreversibleFailureScope::SingleConsumer;
  bool m_active = false;
};

void War3ForceImmediatePresent(D3DPRESENT_PARAMETERS *params) {
  if (!params)
    return;
  if (war3::War3Imgui::isFpsUnlocked())
    params->PresentationInterval = D3DPRESENT_INTERVAL_IMMEDIATE;
}

// Phase 7.108b：Shadow append survey — 实际进入 shadowCasters 的 rawcode 分布。
// 用于直接验证：path blocker 拦截后是否还有漏网到 caster 集合。
// 不做拦截动作，只观察。
//
// Phase 7.128：默认禁用，env=DXVK_WAR3_SHADOW_APPEND_SURVEY=1 才启用。
// 每帧 100-200 次调用，每次 fetch_add + 16 槽线性扫描，关掉能节约 10-20μs/帧。
std::array<std::atomic<uint32_t>, 16> g_shadowAppendRawcodeSamples{};
std::atomic<uint64_t> g_shadowAppendRawcodeUniqueCount{0};
std::atomic<uint64_t> g_shadowAppendTotalCount{0};

inline bool ShadowAppendSurveyEnabled() {
  static const bool enabled = []() {
    const char* env = std::getenv("DXVK_WAR3_SHADOW_APPEND_SURVEY");
    return env != nullptr && env[0] != '\0' && env[0] != '0';
  }();
  return enabled;
}

inline void NoteShadowAppendRawcode(uint32_t rawcode) {
  if (!ShadowAppendSurveyEnabled())
    return;
  g_shadowAppendTotalCount.fetch_add(1, std::memory_order_relaxed);
  if (rawcode == 0u)
    return;
  uint32_t freeSlot = 16u;
  for (uint32_t i = 0u; i < 16u; ++i) {
    const uint32_t cur =
        g_shadowAppendRawcodeSamples[i].load(std::memory_order_relaxed);
    if (cur == rawcode)
      return;
    if (cur == 0u && freeSlot == 16u)
      freeSlot = i;
  }
  if (freeSlot < 16u) {
    uint32_t expected = 0u;
    if (g_shadowAppendRawcodeSamples[freeSlot].compare_exchange_strong(
            expected, rawcode, std::memory_order_relaxed)) {
      g_shadowAppendRawcodeUniqueCount.fetch_add(
          1, std::memory_order_relaxed);
    }
  }
}

// Phase 7.136：path blocker 拦截路径分桶 dxvk.log helper。
// 用户报告 EntryGate/EarlyBypass log 命中 YT* 但视觉仍可见 path blocker 阴影。
// 这意味着 path blocker 走了**其他 9+ 个拦截分桶**之一，但那些分桶只 ++counter
// 不写 log，所以无法直接验证。本 helper 给所有分桶统一格式：前 30 个 unique
// (rawcode, via) 组合各写 1 行到 dxvk.log。
//
// 注意：我们之前的 EntryGate/EarlyBypass log 已经存在，本 helper 用于 *其他*
// 分桶（Producer/FastAppend/DirectGrouped/StaticSupplement/AppendVbBlend/
// AppendEntry/LegacyCapture）。
inline void NotePathBlockerRejectLog(uint32_t rawcode, uint32_t jHandle,
                                     const char* via) {
  if (rawcode == 0u || via == nullptr)
    return;
  // 全局 dedup：(rawcode << 4) | via_hash，前 30 个 unique 写 log。
  // via 用 string pointer 简单 hash（每个 string literal 都是稳定指针）。
  const uint64_t key =
      (uint64_t(rawcode) << 16) ^ (reinterpret_cast<uintptr_t>(via) & 0xFFFFu);
  static std::atomic<uint32_t> s_logCount{0};
  static std::atomic<uint64_t> s_logged[32] = {};
  const uint32_t totalLogged =
      s_logCount.load(std::memory_order_relaxed);
  if (totalLogged >= 30u)
    return;
  bool firstSeen = true;
  uint32_t freeSlot = 32u;
  for (uint32_t i = 0u; i < 32u; ++i) {
    const uint64_t cur = s_logged[i].load(std::memory_order_relaxed);
    if (cur == key) {
      firstSeen = false;
      break;
    }
    if (cur == 0u && freeSlot == 32u)
      freeSlot = i;
  }
  if (!firstSeen || freeSlot >= 32u)
    return;
  uint64_t expected = 0u;
  if (!s_logged[freeSlot].compare_exchange_strong(expected, key,
                                                  std::memory_order_relaxed))
    return;
  const uint32_t logIdx = s_logCount.fetch_add(1, std::memory_order_relaxed);
  char fc[5] = {char((rawcode >> 24) & 0xFF), char((rawcode >> 16) & 0xFF),
                char((rawcode >> 8) & 0xFF), char(rawcode & 0xFF), 0};
  char buf[200];
  snprintf(buf, sizeof(buf),
           "DXVK War3Hook[Shadow]: PATH BLOCKER REJECT #%u rawcode=0x%08X "
           "(%s) jHandle=0x%X via=%s",
           logIdx + 1, rawcode, fc, unsigned(jHandle), via);
  ::dxvk::Logger::info(buf);
}

} // namespace

namespace war3_diag {
uint64_t QueryShadowAppendTotal() {
  return g_shadowAppendTotalCount.load(std::memory_order_relaxed);
}
uint64_t QueryShadowAppendUnique() {
  return g_shadowAppendRawcodeUniqueCount.load(std::memory_order_relaxed);
}
uint32_t QueryShadowAppendRawcodeAt(uint32_t idx) {
  if (idx >= g_shadowAppendRawcodeSamples.size())
    return 0u;
  return g_shadowAppendRawcodeSamples[idx].load(std::memory_order_relaxed);
}
} // namespace war3_diag

