uint32_t War3GetEnvU32(const char *name, uint32_t fallback) {
  const std::string v = env::getEnvVar(name);
  if (v.empty())
    return fallback;
  char *end = nullptr;
  const unsigned long parsed = std::strtoul(v.c_str(), &end, 0);
  if (end == v.c_str())
    return fallback;
  return static_cast<uint32_t>(parsed);
}

