// Phase 7.137：runtime gate 改成内联 static + atomic bool 缓存。
// 原 War3SemanticSubmitScope 函数每个 sub-scope 调用一次（每个 caster 22 次），
// hot-path 上的非内联函数调用 + ABI return-by-value 开销不容忽视。
// 改成 inline，编译器能 strip 掉 disabled 分支的 ScopedCpuScope 对象创建。
inline bool War3SemanticSubmitBreakdownEnabledFast() {
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_SUBMIT_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

inline bool War3SemanticDirectPhaseBreakdownEnabledFast() {
  // Frame-level DirectGrouped child phases only. Unlike the legacy submit
  // breakdown this does not create a scope per record/draw, so it can expose
  // SnapshotPreselect and Submit structure without multiplying probe overhead
  // by caster count. Keep it opt-in for clean product A/B runs.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_DIRECT_PHASE_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

inline war3::War3PerfMonitor::ScopedCpuScope War3SemanticSubmitScopeFast(
    const char* name) {
  if (!War3SemanticSubmitBreakdownEnabledFast())
    return {};
  return war3::War3PerfMonitor::instance().cpuScope(name);
}

inline uint32_t War3SemanticFastAppendTraceSamplePeriod() {
  static const uint32_t s_period = std::clamp<uint32_t>(
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_FAST_APPEND_TRACE_PERIOD", 32u),
      1u, 4096u);
  return s_period;
}

inline bool War3SemanticFastAppendStatsReuseRuntime() {
  // A successful fast append has already passed the Unit object-kind gate and
  // has already published the canonical dynamic-evidence counter exactly
  // once. Re-running both predicates in noteSubmittedKeys is pure diagnostic
  // work and historically double-counted that evidence.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_FAST_APPEND_STATS_REUSE", 1u) != 0u;
  return s_enabled;
}

inline bool War3SemanticFastAppendStatsReuseVerifierRuntime() {
  // Strong opt-in verifier: repeat the legacy resolver on every successful
  // fast append and abort if the gate/result contract ever diverges.
  static const bool s_enabled =
      War3GetEnvU32(
          "DXVK_WAR3_SEMANTIC_FAST_APPEND_STATS_REUSE_VERIFY", 0u) != 0u;
  return s_enabled;
}

inline bool War3SemanticPaletteInPlaceAppendRuntime() {
  // War3ShadowMatrixPalette owns a fixed 256-matrix array. Building a local
  // value and then moving it into vector still copies the full array. The
  // in-place route default-constructs the identical zero-filled value directly
  // in the destination slot and then fills the live prefix. Keep a runtime A/B
  // gate so isolated tests can compare the two byte-equivalent paths.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_PALETTE_IN_PLACE_APPEND", 1u) != 0u;
  return s_enabled;
}

inline bool War3SampleSemanticFastAppendTrace(uint32_t period) {
  static thread_local uint64_t s_ordinal = 0u;
  return (++s_ordinal % std::max(1u, period)) == 0u;
}

inline bool War3SemanticBuildEligibleBreakdownEnabledFast() {
  // 独立于旧的 SEMANTIC_SUBMIT_BREAKDOWN。旧开关会在每次 BuildPacket
  // 内创建二十多个 scope，诊断本身足以显著放大 BuildEligible。这里仅启用
  // 每帧粗分段和低频 record 采样，允许在产品路径其余探针关闭时取样。
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_BUILD_ELIGIBLE_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

inline uint32_t War3SemanticBuildEligibleTraceSamplePeriod() {
  static const uint32_t s_period = std::clamp<uint32_t>(
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_BUILD_ELIGIBLE_TRACE_PERIOD", 64u),
      1u, 4096u);
  return s_period;
}

inline bool War3SampleSemanticBuildEligibleTrace(uint32_t period) {
  if (period <= 1u)
    return true;
  // 不用固定 ordinal % period：record 顺序本身具有 geoset 周期，固定相位会
  // 系统性偏向 packet-build 或 fast-prebuild。xorshift 只做三次整数运算，
  // 让 Horvitz-Thompson 样本跨 record 位置均匀分散。
  static thread_local uint64_t s_state = 0x9e3779b97f4a7c15ull;
  s_state ^= s_state << 13u;
  s_state ^= s_state >> 7u;
  s_state ^= s_state << 17u;
  return (s_state % period) == 0u;
}

inline uint64_t War3BuildEligibleQpcOverheadTicks() {
  // 微秒级 phase 的相邻 QPC 差值包含一次 QueryPerformanceCounter 固定成本。
  // 取进程内 64 次 back-to-back 最小值作为保守下界，每个样本 phase 扣一次；
  // 校准只在专用 breakdown 首次开启时发生。
  static const uint64_t s_ticks = []() {
    uint64_t minimum = std::numeric_limits<uint64_t>::max();
    for (uint32_t i = 0u; i < 64u; ++i) {
      const int64_t begin = dxvk::high_resolution_clock::get_counter();
      const int64_t end = dxvk::high_resolution_clock::get_counter();
      if (end > begin)
        minimum = std::min(minimum, uint64_t(end - begin));
    }
    return minimum == std::numeric_limits<uint64_t>::max() ? 0u : minimum;
  }();
  return s_ticks;
}

