    static_cast<size_t>(War3FallbackAppendPhase::Count);

struct War3FallbackAppendTraceTls {
  bool owned = false;
  bool active = false;
  uint32_t sampleWeight = 1u;
  uint64_t qpcOverheadTicks = 0u;
  std::array<uint64_t, kWar3FallbackAppendPhaseCount> ticks = {};
  std::array<uint32_t, kWar3FallbackAppendPhaseCount> calls = {};
};

static thread_local War3FallbackAppendTraceTls g_war3FallbackAppendTraceTls;

class War3FallbackAppendRawTiming;
static thread_local War3FallbackAppendRawTiming*
    g_war3FallbackAppendRawTiming = nullptr;

class War3FallbackAppendTraceSession final {
public:
  War3FallbackAppendTraceSession(bool requested, uint64_t qpcOverheadTicks)
      : m_active(requested && !g_war3FallbackAppendTraceTls.owned) {
    if (!m_active)
      return;

    auto& trace = g_war3FallbackAppendTraceTls;
    trace.owned = true;
    trace.ticks.fill(0u);
    trace.calls.fill(0u);
    trace.sampleWeight = 1u;
    trace.qpcOverheadTicks = qpcOverheadTicks;
  }

  ~War3FallbackAppendTraceSession() {
    if (m_active) {
      g_war3FallbackAppendTraceTls.active = false;
      g_war3FallbackAppendTraceTls.owned = false;
      g_war3FallbackAppendTraceTls.sampleWeight = 1u;
    }
  }

  War3FallbackAppendTraceSession(const War3FallbackAppendTraceSession&) =
      delete;
  War3FallbackAppendTraceSession& operator=(
      const War3FallbackAppendTraceSession&) = delete;

  bool active() const {
    return m_active;
  }

  void arm(uint32_t sampleWeight) {
    if (!m_active)
      return;
    auto& trace = g_war3FallbackAppendTraceTls;
    trace.sampleWeight = std::max(1u, sampleWeight);
    trace.active = true;
  }

  void disarm() {
    if (!m_active)
      return;
    auto& trace = g_war3FallbackAppendTraceTls;
    trace.active = false;
    trace.sampleWeight = 1u;
  }

  const std::array<uint64_t, kWar3FallbackAppendPhaseCount>& ticks() const {
    return g_war3FallbackAppendTraceTls.ticks;
  }

  const std::array<uint32_t, kWar3FallbackAppendPhaseCount>& calls() const {
    return g_war3FallbackAppendTraceTls.calls;
  }

private:
  bool m_active = false;
};

class War3FallbackAppendRawTiming final {
public:
  War3FallbackAppendRawTiming()
      : m_active(g_war3FallbackAppendTraceTls.active),
        m_previous(g_war3FallbackAppendRawTiming) {
    if (m_active) {
      g_war3FallbackAppendRawTiming = this;
      enter(War3FallbackAppendPhase::EntryPolicy);
    }
  }

  ~War3FallbackAppendRawTiming() {
    if (m_active) {
      closeCurrent(dxvk::high_resolution_clock::get_counter());
      g_war3FallbackAppendRawTiming = m_previous;
    }
  }

  War3FallbackAppendRawTiming(const War3FallbackAppendRawTiming&) = delete;
  War3FallbackAppendRawTiming& operator=(
      const War3FallbackAppendRawTiming&) = delete;

  inline void enter(War3FallbackAppendPhase phase) {
    if (!m_active)
      return;
    const int64_t now = dxvk::high_resolution_clock::get_counter();
    closeCurrent(now);
    m_phase = phase;
    m_begin = now;
    g_war3FallbackAppendTraceTls.calls[static_cast<size_t>(phase)] +=
        g_war3FallbackAppendTraceTls.sampleWeight;
  }

private:
  inline void closeCurrent(int64_t now) {
    if (m_begin == 0 || m_phase == War3FallbackAppendPhase::Count)
      return;
    if (now > m_begin) {
      const uint64_t elapsed = uint64_t(now - m_begin);
      const uint64_t overhead =
          g_war3FallbackAppendTraceTls.qpcOverheadTicks;
      g_war3FallbackAppendTraceTls.ticks[static_cast<size_t>(m_phase)] +=
          (elapsed > overhead ? elapsed - overhead : 0u) *
          g_war3FallbackAppendTraceTls.sampleWeight;
    }
  }

  bool m_active = false;
  War3FallbackAppendRawTiming* m_previous = nullptr;
  War3FallbackAppendPhase m_phase = War3FallbackAppendPhase::Count;
  int64_t m_begin = 0;
};

inline void War3EnterFallbackAppendPhase(War3FallbackAppendPhase phase) {
  if (g_war3FallbackAppendRawTiming != nullptr)
    g_war3FallbackAppendRawTiming->enter(phase);
}

