class War3PopulateReadableRegionCache final {
public:
  explicit War3PopulateReadableRegionCache(bool enabled)
      : m_enabled(enabled) {
  }

  bool isReadable(const void* ptr, size_t size) {
    if (!m_enabled)
      return dxvk::war3::IsReadableRange(ptr, size);
    if (ptr == nullptr || size == 0u)
      return false;

    const uintptr_t start = reinterpret_cast<uintptr_t>(ptr);
    if (size > std::numeric_limits<uintptr_t>::max() - start)
      return false;
    const uintptr_t end = start + size;

    for (uint32_t i = 0u; i < m_regionCount; ++i) {
      const auto& region = m_regions[i];
      if (start < region.begin || start >= region.end)
        continue;
      if (!region.readable)
        return false;
      if (end <= region.end)
        return true;
      // Preserve the old multi-region behavior for the rare crossing range.
      return dxvk::war3::IsReadableRange(ptr, size);
    }

    MEMORY_BASIC_INFORMATION mbi = {};
    if (::VirtualQuery(reinterpret_cast<LPCVOID>(start), &mbi, sizeof(mbi)) ==
        0u) {
      return false;
    }
    const uintptr_t regionBegin =
        reinterpret_cast<uintptr_t>(mbi.BaseAddress);
    if (mbi.RegionSize == 0u ||
        mbi.RegionSize >
            std::numeric_limits<uintptr_t>::max() - regionBegin) {
      return false;
    }
    const uintptr_t regionEnd = regionBegin + mbi.RegionSize;
    const bool readable =
        mbi.State == MEM_COMMIT && dxvk::war3::IsReadableProtect(mbi.Protect) &&
        (mbi.Protect & (PAGE_GUARD | PAGE_NOACCESS)) == 0u;
    const uint32_t slot =
        m_regionCount < m_regions.size()
            ? m_regionCount++
            : m_replaceIndex++ % uint32_t(m_regions.size());
    m_regions[slot] = {regionBegin, regionEnd, readable};
    if (!readable)
      return false;
    if (end <= regionEnd)
      return true;
    return dxvk::war3::IsReadableRange(ptr, size);
  }

  static bool Validate(void* context, const void* ptr, size_t size) {
    return context != nullptr &&
        static_cast<War3PopulateReadableRegionCache*>(context)->isReadable(
            ptr, size);
  }

private:
  struct Region {
    uintptr_t begin = 0u;
    uintptr_t end = 0u;
    bool readable = false;
  };

  bool m_enabled = false;
  std::array<Region, 32> m_regions = {};
  uint32_t m_regionCount = 0u;
  uint32_t m_replaceIndex = 0u;
};

