inline bool War3ShadowCaptureGateBreakdownRuntime() {
  // 默认关闭：递归热点调查时才启用。采样结果在帧末按 Gates 精确总 ticks
  // 归一化，因此诊断树保持加和闭合。
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SHADOW_GATE_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

bool War3SemanticRejectAlphaBlendCasterRuntime() {
  // A complete UV/texture payload is sufficient to reproduce a binary
  // alpha-test (cutout) material, but it does not turn a true alpha-blended
  // visual layer into a valid shadow caster. Treating AlphaBlend as Cutout
  // produces the large hard-edged effect cards seen for transient spell and
  // particle geosets. Keep the unsafe behavior available only as an explicit
  // diagnostic rollback.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SEMANTIC_REJECT_ALPHA_BLEND_CASTER", 1u) != 0u;
  return s_enabled;
}

inline bool War3ShadowDrawTimeCaptureBreakdownRuntime() {
  // Default-off recursive split of the exact DrawTimeCapture child. It shares
  // the outer ShadowCapture sampling admission with Gates, then frame-flush
  // normalization closes the mutually-exclusive phases to the exact parent.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SHADOW_DRAWTIME_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

inline bool War3ShadowCapturePostBreakdownRuntime() {
  // Default-off recursive probe for the legacy-capture body after all Gates.
  // Raw sampled phases are normalized to the exact always-on PostGate timer at
  // frame flush, so the tree remains closed. Each leaf subtracts the measured
  // QPC lower bound; nested probes can still add a small observer tax to the
  // exact parent while this explicit diagnostic mode is enabled.
  // The recursive timer is an observer, not a rendering route. Keep it
  // unreachable in the default Release build, but allow the separately
  // configured observer DLL to attribute PostGate without enabling Consume.
  if constexpr (!dxvk::war3::render::
                     kDevelopmentShadowObserversEnabled)
    return false;
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_SHADOW_CAPTURE_BREAKDOWN", 0u) != 0u;
  return s_enabled;
}

