inline DxvkResourceBufferInfo War3PinnedAllocationSliceInfo(
    const Rc<DxvkResourceAllocation>& allocation,
    VkDeviceSize localOffset, VkDeviceSize requestedBytes) {
  if (allocation == nullptr)
    return {};
  const DxvkResourceBufferInfo whole = allocation->getBufferInfo();
  const auto range = dxvk::war3::render::MakeWar3PinnedUploadRange(
      uint64_t(whole.size), uint64_t(localOffset), uint64_t(requestedBytes));
  if (!range.valid || whole.buffer == VK_NULL_HANDLE)
    return {};
  DxvkResourceBufferInfo result = whole;
  result.offset += VkDeviceSize(range.offset);
  result.size = VkDeviceSize(range.length);
  if (result.mapPtr != nullptr)
    result.mapPtr = reinterpret_cast<uint8_t*>(result.mapPtr) + range.offset;
  if (result.gpuAddress != 0u)
    result.gpuAddress += VkDeviceAddress(range.offset);
  return result;
}

enum class War3ProducerClaimObserveMode : uint8_t {
  Off = 0u,
  Observe = 1u,
  Consume = 2u,
};

War3ProducerClaimObserveMode War3ProducerClaimObserveModeRuntime() {
  // The reduced pre-build identity has not yet proved collision-free parity
  // with the post-build exact-owner key.  Release is always Off; a dedicated
  // observer build accepts only mode 1 and mode 2 remains unreachable.
  if constexpr (!dxvk::war3::render::kDevelopmentShadowObserversEnabled)
    return War3ProducerClaimObserveMode::Off;
  static const auto s_mode =
      dxvk::war3::render::ParseShadowObserverBuildMode(War3GetEnvU32(
          "DXVK_WAR3_SEMANTIC_PRODUCER_CLAIM_LEDGER", 0u));
  return s_mode == dxvk::war3::render::War3ShadowObserverBuildMode::Observe
      ? War3ProducerClaimObserveMode::Observe
      : War3ProducerClaimObserveMode::Off;
}

inline bool War3LegacyPerDrawSemanticScopesRuntime() {
  // The coarse profiler scope builds multiple std::string paths, touches the
  // section cache and queues a delta on every push/pop. BuildSemantic and
  // NativeHint execute hundreds of times per frame, so always-on coarse scopes
  // materially perturb the path they are intended to measure. Keep the old
  // behavior as an explicit same-DLL A/B fallback; normal reports use the
  // sampled detail scope plus the raw-QPC aggregate tree.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_LEGACY_PER_DRAW_SEMANTIC_SCOPES", 0u) != 0u;
  return s_enabled;
}

inline bool War3NativeHintProducerlessSkipRuntime() {
  // The only NativeShadowHint producers are compiled behind
  // kWar3ShadowProjectorNativeHintEnabled. When that flag is false the
  // registry is empty for the entire process lifetime, so taking its mutex and
  // probing up to thirteen keys per draw cannot affect any result. Keep a
  // same-DLL rollback for A/B measurement and for emergency diagnosis.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_NATIVE_HINT_PRODUCERLESS_SKIP", 1u) != 0u;
  return s_enabled;
}

inline bool War3DrawTimeCacheIteratorReuseRuntime() {
  // FingerprintAndDedup already probes the cache. When an entry exists but
  // needs a fresh copy, the historical operator[] immediately repeated the
  // same hash lookup in CacheRecordSetup. Reuse the still-valid iterator;
  // misses retain operator[] insertion and exact default-value semantics.
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_DRAWTIME_CACHE_ITERATOR_REUSE", 1u) != 0u;
  return s_enabled;
}

inline bool War3DrawTimeVBCacheRuntime() {
  // Legacy cross-frame cache/shortcut diagnosis gate. Disabling it is
  // fail-closed for every consumer which may reuse a snapshot outside the
  // exact current-frame producer. The separately gated Stage11 current-frame
  // geometry path below may still capture owned GPU bytes, but it can only
  // publish an entry whose frameSerial equals the active persistent frame.
  //
  // 2026-07-27 correctness containment: physical-screen validation still
  // observed whole-shadow flicker and an intermittent world-origin polygon
  // after the two shortcut producers were disabled. The only A/B that removed
  // the large transient geometry was the master cache-off path, so the cache
  // now stays fail-closed by default while the final-caster trace identifies
  // the remaining unsafe consumer tuple. Explicit =1 is diagnostic only.
  if constexpr (dxvk::war3::internal::
                    kReleaseFreezeExperimentalShadowRoutes)
    return false;
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_DRAWTIME_VB_CACHE", 0u) != 0u;
  return s_enabled;
}

inline bool War3DrawTimeCurrentFrameGeometryRuntime() {
  // Production-safe replacement for the over-broad cache master gate.
  //
  // Stage11 still needs an owned GPU copy of the exact draw currently being
  // submitted: the canonical semantic packet does not cover every visible
  // geoset, and disabling this capture removed roughly half of the unit
  // caster parts in dense scenes.  This gate permits capture plus the
  // exact-current-frame DrawTimeGeometry producer only.  It does not enable
  // the generic cross-frame override, GPU-skin cache preflight, fast append,
  // prebuild bypass, or the legacy alpha payload cache guarded by
  // War3DrawTimeVBCacheRuntime().
  static const bool s_enabled =
      War3GetEnvU32("DXVK_WAR3_DRAWTIME_CURRENT_FRAME_GEOMETRY", 1u) != 0u;
  return s_enabled;
}

