inline bool War3SampleShadowCaptureGateTrace(uint32_t period) {
  if (period <= 1u)
    return true;
  static thread_local uint64_t s_state = 0xd1b54a32d192ed03ull;
  s_state ^= s_state << 13u;
  s_state ^= s_state >> 7u;
  s_state ^= s_state << 17u;
  return (s_state % period) == 0u;
}

class War3ShadowCaptureGateRawTiming final {
public:
  War3ShadowCaptureGateRawTiming(
      bool active, uint32_t sampleWeight, uint64_t qpcOverheadTicks,
      std::array<uint64_t, kWar3ShadowCaptureGatePhaseCount>& ticks,
      std::array<uint32_t, kWar3ShadowCaptureGatePhaseCount>& calls)
      : m_active(active),
        m_sampleWeight(std::max(1u, sampleWeight)),
        m_qpcOverheadTicks(qpcOverheadTicks),
        m_ticks(ticks),
        m_calls(calls) {
  }

  ~War3ShadowCaptureGateRawTiming() {
    if (m_active && m_begin != 0)
      closeCurrent(dxvk::high_resolution_clock::get_counter());
  }

  War3ShadowCaptureGateRawTiming(
      const War3ShadowCaptureGateRawTiming&) = delete;
  War3ShadowCaptureGateRawTiming& operator=(
      const War3ShadowCaptureGateRawTiming&) = delete;

  inline void enter(War3ShadowCaptureGatePhase phase) {
    if (!m_active)
      return;
    const int64_t now = dxvk::high_resolution_clock::get_counter();
    closeCurrent(now);
    m_phase = phase;
    m_begin = now;
    m_calls[static_cast<size_t>(phase)] += m_sampleWeight;
  }

  inline void pause() {
    if (!m_active)
      return;
    closeCurrent(dxvk::high_resolution_clock::get_counter());
    m_phase = War3ShadowCaptureGatePhase::Count;
    m_begin = 0;
  }

private:
  inline void closeCurrent(int64_t now) {
    if (m_begin == 0 || m_phase == War3ShadowCaptureGatePhase::Count)
      return;
    if (now > m_begin) {
      const size_t index = static_cast<size_t>(m_phase);
      const uint64_t elapsed = uint64_t(now - m_begin);
      const uint64_t corrected = elapsed > m_qpcOverheadTicks
          ? elapsed - m_qpcOverheadTicks : 0u;
      m_ticks[index] += corrected * m_sampleWeight;
    }
  }

  bool m_active = false;
  uint32_t m_sampleWeight = 1u;
  uint64_t m_qpcOverheadTicks = 0u;
  std::array<uint64_t, kWar3ShadowCaptureGatePhaseCount>& m_ticks;
  std::array<uint32_t, kWar3ShadowCaptureGatePhaseCount>& m_calls;
  War3ShadowCaptureGatePhase m_phase = War3ShadowCaptureGatePhase::Count;
  int64_t m_begin = 0;
};

